const minPath = (grid, k) => {
  const n = grid.length;
  const pos = new Array(n * n + 1);

  for (let r = 0; r < n; r++) {
    for (let c = 0; c < n; c++) {
      pos[grid[r][c]] = [r, c];
    }
  }

  let [r, c] = pos[1];
  const result = [];

  for (let i = 0; i < k; i++) {
    result.push(grid[r][c]);

    let bestValue = Infinity;
    let bestR = r;
    let bestC = c;

    if (r > 0 && grid[r - 1][c] < bestValue) {
      bestValue = grid[r - 1][c];
      bestR = r - 1;
      bestC = c;
    }

    if (r < n - 1 && grid[r + 1][c] < bestValue) {
      bestValue = grid[r + 1][c];
      bestR = r + 1;
      bestC = c;
    }

    if (c > 0 && grid[r][c - 1] < bestValue) {
      bestValue = grid[r][c - 1];
      bestR = r;
      bestC = c - 1;
    }

    if (c < n - 1 && grid[r][c + 1] < bestValue) {
      bestValue = grid[r][c + 1];
      bestR = r;
      bestC = c + 1;
    }

    r = bestR;
    c = bestC;
  }

  return result;
};

